#!/usr/bin/env python3
"""COSMOS v9.4.3 guarded frontend installer. No external Python dependencies.
Does not modify any file except cosmos-next.html, and only in apply mode.
"""
import argparse,base64,hashlib,json,sys,zlib
from pathlib import Path
SOURCE_SHA='ee75d96029313ae6c2223b12bb624356a7cb417d6f2dc83e133675eae55f8625'
TARGET_SHA='ae8a68b4fa51be911885d1db75481625efe0d2367adc224b3f0ef10f43d1f7fe'
DELTA_B64=''

def sha(text):return hashlib.sha256(text.encode('utf-8')).hexdigest()
def main():
 parser=argparse.ArgumentParser(description='COSMOS v9.4.3 Region News and Full Screen')
 parser.add_argument('--mode',choices=['validate','apply'],required=True)
 args=parser.parse_args()
 file=Path('cosmos-next.html')
 if not file.is_file():sys.exit('Missing cosmos-next.html; run from repository root.')
 current=file.read_text(encoding='utf-8')
 digest=sha(current)
 if digest==TARGET_SHA:
  print('COSMOS v9.4.3 already applied. No changes necessary.')
  return
 if digest!=SOURCE_SHA:
  sys.exit('STOP: frontend source differs from the expected v9.4.2 baseline. No changes applied. Back up and reconcile before retrying. Actual SHA256='+digest)
 raw=zlib.decompress(base64.b64decode(DELTA_B64))
 patches=json.loads(raw.decode('utf-8'))
 lines=current.splitlines(keepends=True)
 for start,end,chunk in reversed(patches):lines[start:end]=[chunk]
 result=''.join(lines)
 if sha(result)!=TARGET_SHA:sys.exit('STOP: Patch checksum mismatch; no changes applied.')
 if 'cosmos943ResponsiveDiscovery' not in result or 'cosmos943WallpaperTools' not in result:
  sys.exit('STOP: v9.4.3 critical markers not present.')
 print('Guarded v9.4.3 patch valid; checksums verified.')
 if args.mode=='validate':
  print('VALIDATE successful — no files modified.')
 else:
  file.write_text(result,encoding='utf-8')
  print('APPLY successful — only cosmos-next.html updated.')
if __name__=='__main__':main()
